import{_ as t,c as n,b as o,o as r}from"./app-CoEY_fQ5.js";const i={};function a(s,e){return r(),n("div",null,e[0]||(e[0]=[o('<p><a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multi-Vendor Marketplace for Shopify</a> has come up with another marketplace shipping feature app for <strong>Indian Merchants</strong>, i.e., <strong>Vamaship</strong>.</p><h2 id="vamaship" tabindex="-1"><a class="header-anchor" href="#vamaship"><span>Vamaship</span></a></h2><p><a href="https://www.vamaship.com/" target="_blank" rel="noopener noreferrer">Vamaship</a> is a SaaS enabled logistics marketplace. Besides, it facilitates shipping via air, ocean, and surface to over 200 countries and 26,000 pin codes within India.</p><p>Using this featured app, the merchants can enable shipment &amp; fulfillment through Vamaship. Moreover, he can automatically generate shipping labels for the same.</p><p>The <strong>Vamaship</strong> feature app is available only with the Multivendor <strong>Pro</strong> <strong>Plan</strong> ($60/month). Moreover, you need to enable the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-shipping/" target="_blank" rel="noopener noreferrer"><strong>Shipping</strong></a> add-on (free) from the featured apps section of the app.</p><p><strong>CHARGES:</strong></p><p>This feature will have an additional charge of <strong>USD 10 per month</strong> over &amp; above your current Multivendor plan.</p><p><strong>NOTE:</strong></p><p>Access to Shipping requires your Shopify store to be on the plan that supports <strong>Real-Time Carrier-Calculated Shipping</strong>.</p><p>THE VAMASHIP SHIPPING FEATURE APP IS AVAILABLE FOR BOTH <strong>RATE CALCULATION &amp; FULFILLMENT</strong>.</p><h2 id="installation" tabindex="-1"><a class="header-anchor" href="#installation"><span>Installation</span></a></h2><p>To enable this &#39;feature app&#39;:</p><p>Go to <strong>multi vendor marketplace admin panel</strong> &gt; click on the <strong>three dots</strong> &gt; click on the &#39;<strong>featured apps&#39;</strong>. Further, <strong>enable</strong> the Vamaship add-on.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Feature-Apps-Admin-1-1.png" alt="feature app"></p><p>Furthermore, agree &amp; approve the charges:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Feature-Apps-Admin-2.png" alt="PAYMENT"></p><p>MultiVendor Marketplace Admin End</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/demo-store-Approve-fees-Shopify-1.png" alt="APPROVE CHARGES"></p><p>Shopify Backend (Admin End)</p><h3 id="configuration-admin-end" tabindex="-1"><a class="header-anchor" href="#configuration-admin-end"><span>Configuration: Admin End</span></a></h3><p>Firstly, go to:<br><strong>Multi-vendor marketplace admin panel</strong> &gt; <strong>configuration</strong> &gt; <strong>shipping</strong> <strong>configuration</strong>. Now, <strong>enable</strong> the shipping method:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Configuration-Admin.png" alt="ENABLE SHIPPING"></p><p>MultiVendor Marketplace Admin End</p><p>After that, you&#39;ll have one more option to configure this shipping.</p><p>So, either click on <strong>Configure Shipping</strong><br> OR<br> Go to <strong>multi vendor marketplace admin panel</strong> &gt; <strong>configuration</strong> &gt; <strong>Vamaship Configuration</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Configuration-Admin-1.png" alt="CONFIGURE SHIPPING"></p><p>MultiVendor Marketplace Admin End</p><p>Hence, this is what the configuration page will look like:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Vamaship-Post-Configuration-Admin-1126x1024.png" alt="Vamaship-Post-Configuration-Admin"></p><p>MultiVendor Marketplace Admin End</p><ul><li><strong>SANDBOX MODE</strong></li></ul><p>If you want to test the functionality of this shipping add-on, enable the sandbox mode. So, use the sandbox mode for testing purposes only.</p><ul><li><strong>AUTOMATIC GENERATE SHIPPING LABEL</strong></li></ul><p>Enable this to automatically generate a shipping label on order fulfillment.</p><ul><li><strong>VAMASHIP ACCESS KEY</strong></li></ul><p>Further, in here, enter the API Username, i.e., the left part of the API key, before the colon. (It will be different for the Production and Development environment.)</p><p>Contact <a href="https://www.vamaship.com/" target="_blank" rel="noopener noreferrer">Vamaship</a> to get the access key.</p><ul><li><p><strong>CHOOSE SERVICE TYPE</strong></p><ul><li><strong>Vamaship Air Domestic</strong>:<br> This is for providing shipping within India via air. <a href="https://vamaship.docs.apiary.io/#" target="_blank" rel="noopener noreferrer">Know more</a>.</li><li><strong>Vamaship Air International:</strong><br> This is international shipping. The seller needs to be located in <strong>Mumbai</strong>, <strong>India</strong>. <a href="https://apiary.io/" target="_blank" rel="noopener noreferrer">Know more</a>.</li><li><strong>Vamaship Surface Domestic:</strong><br> This is for providing shipping within India via surface. <a href="https://vamashipsurface.docs.apiary.io/#" target="_blank" rel="noopener noreferrer">Know more</a>.</li></ul></li><li><p><strong>SHIPPING LABEL COST BORNE BY</strong></p></li></ul><p>Further, choose who will bear the shipping label charges, thus, the admin or the seller. (This is an extra cost apart from what the customer has paid.)</p><ul><li><strong>USAGE AS</strong></li></ul><p>Select how you want to use Vamaship: For fulfilment or Both fulfilment &amp; shipping.</p><p><strong>Note</strong>: If you are using it for fulfillment only then customers will not get Vamaship shipping rates on the checkout page. That is, you will only be able to fulfil orders via Vamaship.</p><h2 id="set-shipping-method-for-sellers" tabindex="-1"><a class="header-anchor" href="#set-shipping-method-for-sellers"><span>Set Shipping Method for Sellers:</span></a></h2><p>The admin can further set the shipping methods for his sellers. So, go to <strong>multi vendor marketplace admin panel</strong> &gt; <strong>Sellers</strong> &gt; <strong>Seller Listing</strong> &gt; <strong>Edit</strong> (under <strong>Action</strong>).<br> On the edit seller page, the admin will have the following block:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Edit-Seller-Admin-1.png" alt="SET SHIPPING AS DEFAULT"></p><p>MultiVendor Marketplace Admin End</p><p>The admin can set any shipping enabled on his multivendor marketplace as default also.</p><p>Further, the admin can view all the sellers which are using this shipping method by going to:</p><p><strong>Multi-vendor marketplace admin panel</strong> &gt; <strong>configuration</strong> &gt; <strong>shipping</strong> <strong>configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Configuration-Admin-2.png" alt="VIEW SELLERS"></p><p>MultiVendor Marketplace Admin End</p><h2 id="make-shipping-address-phone-number-mandatory" tabindex="-1"><a class="header-anchor" href="#make-shipping-address-phone-number-mandatory"><span>Make <strong>Shipping</strong> <strong>Address Phone Number</strong> Mandatory</span></a></h2><p>The admin needs to make the <strong>Shipping</strong> <strong>address phone number mandatory</strong> at the time of <strong>checkout</strong>.</p><p>So, go to <strong>Shopify Backend</strong> &gt; <strong>Settings</strong> &gt; <strong>Checkout</strong> &gt; Under <strong>Form Options</strong>, make <strong>Shipping</strong> <strong>address phone number</strong> as <strong>Required</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/demo-store-Checkout-Shopify.png" alt="PHONE NUMBER REQUIRED"></p><p>Shopify Backend (Admin End)</p><h3 id="configuration-seller-end" tabindex="-1"><a class="header-anchor" href="#configuration-seller-end"><span>Configuration: Seller End</span></a></h3><p><strong>Note: Seller address &amp; phone number is mandatory.</strong></p><p>Further, the seller can configuration Vamashipping from his panel.</p><p>So, go to <strong>multi vendor marketplace seller panel</strong> &gt; <strong>configuration</strong> &gt; <strong>shipping configuration</strong> &gt; <strong>enable</strong> the shipping:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-Configuration-Seller-•-Multivendor-MarketPlace.png" alt="ENABLE"></p><p>MultiVendor Marketplace Seller End</p><p>Further, go to <strong>Global Configuration</strong>:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-Configuration-Seller-•-Multivendor-MarketPlace-1.png" alt="GLOBAL CONFIGURATION"></p><p>MultiVendor Marketplace Seller End</p><p>Moreover, from here, the seller can do the <strong>SHIPPING PACKET CONFIGURATION</strong>:</p><p><strong>Note:</strong> 150 cm &gt; <strong>LBH</strong> &gt; 1 cm<br> In the case of <strong>Vamaship Air Domestic</strong>: 150 cm &gt; <strong>LBH</strong> &gt; 3 cm</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-Configuration-Seller-•-Multivendor-MarketPlace-2.png" alt="SHIPPING PACKET CONFIGURATION"></p><p>MultiVendor Marketplace Seller End</p><p>Further, the seller can set the shipping method as <strong>by-default</strong>. So that every single product created it will have <strong>Vamaship Shipping</strong> as the <strong>by-default shipping method</strong>.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-Configuration-Seller-•-Multivendor-MarketPlace-3.png" alt="SET AS DEFAULT"></p><p>MultiVendor Marketplace Seller End</p><p>If not this, the seller can set the shipping method on individual products while adding/editing them.</p><p>So, go to <strong>Multi-vendor marketplace seller panel</strong> &gt; <strong>Products</strong> &gt;<strong>Product Listing</strong> &gt; <strong>Add</strong>/<strong>Edit</strong> the Product:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Screenshot-from-2019-09-16-14-38-02.png" alt="REQUIRES SHIPPING"></p><p>MultiVendor Marketplace Seller End</p><h2 id="shopify-store-frontend" tabindex="-1"><a class="header-anchor" href="#shopify-store-frontend"><span>Shopify Store Frontend</span></a></h2><p>Further, the customer will have an option to select the shipping method as <strong>Vamaship</strong> after entering the information:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Shipping-demo-store-Checkout.png" alt="CHECKOUT PAGE"></p><p>Shopify Storefront</p><h2 id="shipping-label-generation" tabindex="-1"><a class="header-anchor" href="#shipping-label-generation"><span>Shipping Label Generation</span></a></h2><p>Seller will have an option to generate a shipping label from their seller panel. Also, shipping labels can only be generated for <strong>fulfilled orders</strong>.</p><p>So, go to <strong>Multi-vendor marketplace seller panel</strong> &gt; <strong>Orders</strong> &gt; <strong>Order Listing</strong> &gt; <strong>View</strong> (under <strong>Action</strong>). In ADDITIONAL ORDER DETAILS, click on <strong>Actions</strong> &gt; <strong>Print Shipping Label</strong>:</p><p>Moreover, this block will have the information regarding who is bearing the shipping label charges. (Refer to the screenshot below.)</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Order-Details-Seller-•-Multivendor-MarketPlace-1.png" alt="PRINT SHIPPING LABEL "></p><p>Furthermore, this is how the shipping label will be downloaded in pdf form:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/09/Screenshot-from-2019-09-16-17-10-17.png" alt="SHIPPING LABEL"></p><p>Vamaship Shipping Label</p>',88)]))}const l=t(i,[["render",a]]),g=JSON.parse('{"path":"/zenith/Featured-App/Shipping/VAMASHIP.html","title":"VAMASHIP SHIPPING","lang":"en-US","frontmatter":{"title":"VAMASHIP SHIPPING","description":"VAMASHIP SHIPPING","date":"2025-07-18T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":2,"title":"Vamaship","slug":"vamaship","link":"#vamaship","children":[]},{"level":2,"title":"Installation","slug":"installation","link":"#installation","children":[{"level":3,"title":"Configuration: Admin End","slug":"configuration-admin-end","link":"#configuration-admin-end","children":[]}]},{"level":2,"title":"Set Shipping Method for Sellers:","slug":"set-shipping-method-for-sellers","link":"#set-shipping-method-for-sellers","children":[]},{"level":2,"title":"Make Shipping Address Phone Number Mandatory","slug":"make-shipping-address-phone-number-mandatory","link":"#make-shipping-address-phone-number-mandatory","children":[{"level":3,"title":"Configuration: Seller End","slug":"configuration-seller-end","link":"#configuration-seller-end","children":[]}]},{"level":2,"title":"Shopify Store Frontend","slug":"shopify-store-frontend","link":"#shopify-store-frontend","children":[]},{"level":2,"title":"Shipping Label Generation","slug":"shipping-label-generation","link":"#shipping-label-generation","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"zenith/Featured-App/Shipping/VAMASHIP.md"}');export{l as comp,g as data};
